class Solution:
    def earliestSecondToMarkIndices(self, nums: List[int], changeIndices: List[int]) -> int:
        n = len(nums)
        m = len(changeIndices)

        # Check if all indices can be marked at all
        if len(set(changeIndices)) != n:
            return -1

        def can_mark(seconds):
            last_occurrence = {}
            for i in range(seconds):
                last_occurrence[changeIndices[i]] = i

            if len(last_occurrence) != n:
                return False

            current_nums = list(nums)
            decrements_needed = {}
            for i in range(n):
                decrements_needed[i + 1] = nums[i]

            available_time = [0] * m
            for idx, time in last_occurrence.items():
                available_time[time] = idx

            used_decrements = 0
            for t in range(seconds):
                idx_to_change = available_time[t]
                if idx_to_change != 0:
                    target_idx = idx_to_change - 1
                    if decrements_needed[idx_to_change] > 0:
                        decs_to_make = decrements_needed[idx_to_change]
                        if decs_to_make <= t - used_decrements:
                            decrements_needed[idx_to_change] = 0
                            used_decrements += decs_to_make
                        else:
                            return False
                    else:
                        continue
                else:
                    continue

            for i in range(1, n + 1):
                if decrements_needed[i] > 0:
                    return False
            return True

        left, right = 1, m
        ans = -1

        while left <= right:
            mid = (left + right) // 2
            if can_mark(mid):
                ans = mid
                right = mid - 1
            else:
                left = mid + 1

        return ans
